window.AAQ_ASSIGN = {"unit": 3, "title": "Practical Microbiology and Infectious Diseases", "aims": [{"aim": "A", "title": "Understand the classification and nature of microorganisms"}, {"aim": "B", "title": "Examine the transmission and treatments of infectious diseases"}, {"aim": "C", "title": "Explore the application of techniques to culture and identify microorganisms"}, {"aim": "D", "title": "Investigate the effect of antimicrobial agents on the growth of microorganisms"}], "criteria": [{"code": "A.P1", "aims": "A", "grade": "P", "n": 1, "text": "Describe the characteristics that are used to classify microorganisms."}, {"code": "A.P2", "aims": "A", "grade": "P", "n": 2, "text": "Describe the roles of structures found in microorganisms and factors affecting growth."}, {"code": "A.P3", "aims": "A", "grade": "P", "n": 3, "text": "Describe the virulence mechanisms of disease- causing microorganisms."}, {"code": "A.M1", "aims": "A", "grade": "M", "n": 1, "text": "Explain how characteristics are used to classify microorganisms."}, {"code": "A.M2", "aims": "A", "grade": "M", "n": 2, "text": "Explain how virulence mechanisms of microorganisms cause infection."}, {"code": "A.D1", "aims": "A", "grade": "D", "n": 1, "text": "Compare the virulence mechanisms of different groups of disease- causing microorganisms."}, {"code": "B.P4", "aims": "B", "grade": "P", "n": 4, "text": "Describe the development of different types of infectious disease."}, {"code": "B.P5", "aims": "B", "grade": "P", "n": 5, "text": "Describe the prevention and treatment of the different types of infectious disease"}, {"code": "B.M3", "aims": "B", "grade": "M", "n": 3, "text": "Discuss the development of infectious diseases and their associated prevention and treatment strategies."}, {"code": "B.D2", "aims": "B", "grade": "D", "n": 2, "text": "Evaluate the prevention and treatment of the different types of infectious disease and the impact of current issues in the use of these treatments."}, {"code": "C.P6", "aims": "C", "grade": "P", "n": 6, "text": "Carry out morphological studies, microscopy and staining techniques to identify microorganisms."}, {"code": "C.M4", "aims": "C", "grade": "M", "n": 4, "text": "Discuss the techniques used to identify and cultivate microorganisms in terms of the quality of results obtained."}, {"code": "C.D3", "aims": "C", "grade": "D", "n": 3, "text": "Evaluate the microscopy and microbiological practical techniques used and skills developed."}, {"code": "C.P7", "aims": "C", "grade": "P", "n": 7, "text": "Correctly select and use aseptic technique to cultivate microorganisms."}, {"code": "C.M5", "aims": "C", "grade": "M", "n": 5, "text": "Correctly select and use aseptic technique to grow and measure the growth of microorganisms, including the use of serial dilutions and counting techniques."}, {"code": "C.D4", "aims": "C", "grade": "D", "n": 4, "text": "Correctly use aseptic enumeration techniques and make judgements on the accuracy of the procedures used."}, {"code": "D.P8", "aims": "D", "grade": "P", "n": 8, "text": "Cultivate microorganisms to accurately measure the effects of antimicrobials on their growth"}, {"code": "D.M6", "aims": "D", "grade": "M", "n": 6, "text": "Interpret data collected in order to reach a conclusion, considering the impact on prevention and treatment of disease."}, {"code": "D.D5", "aims": "D", "grade": "D", "n": 5, "text": "Evaluate the methods, techniques and data collected to determine the effect of antimicrobials on the growth of microorganisms."}], "guidance": [{"aims": "A", "paras": ["For distinction standard, students will compare virulence mechanisms of the main subgroups of disease-causing microorganism (bacteria, fungi, protists, and viruses). They will consider the relevance of these mechanisms and how they combine to influence the pathogenicity of the microorganism. The minimum expected would be one pathogen from each group (bacteria, fungi, protists, and viruses). For merit standard, students will explain the classification methods for bacteria, fungi, protists, and viruses. Students must explain the Baltimore system of classification of viruses and explain how each subgroup is different in their mode of infectivity. Students will be able to explain the basis for the classification of bacteria based on features such as morphology, staining properties of the organism and oxygen requirements in bacteria. They will explain the virulence mechanisms used by bacteria, fungi, protists, and viruses using named examples of how these cause infection. Students are expected to use annotated diagrams to illustrate their explanations. The diagrams will be clearly labelled and accurate. For pass standard, students will describe the characteristics used to classify microorganisms. They will describe the main features of the different types of microorganism using a named example from each of the subgroups (bacteria, fungi, protists, and viruses). The roles of the structures found in bacteria, fungi, protists, and viruses must be described. Named examples and annotated diagrams will be used to illustrate their descriptions. Students will describe the growth of microorganisms in terms of cell division, oxygen requirements, temperature factors and the features of growth curves. They will also describe the virulence factors identified in the unit content."]}, {"aims": "B", "paras": ["For distinction standard, students will evaluate the treatments of at least three different types of disease caused by the types of pathogen identified in the section B3 of the unit content, and the impact of current issues in the use of these treatments. They will demonstrate a thorough understanding of the issues facing the treatment of infectious diseases. They will provide an evaluation of the causes of antibiotic resistance and problems with creating vaccinations owing to mutations and antigenic variation. They could evaluate some alternative/innovative treatments. Students will demonstrate a thorough understanding of the issues facing the treatment of infectious diseases. They will provide a detailed explanation of some of the contributory events that have led to antibiotic resistance, the evasion of the immune system by some pathogens and problems with creating vaccinations owing to mutations and antigenic variation. They will then evaluate some alternative/innovative treatments. For merit standard, students will use three examples to discuss the development of infectious diseases. They will compare how different invasive microorganisms disrupt the functions of host cells and organs and explain the chain of infection for each disease. They will discuss the modes of action of the available treatment and prevention strategies for each of the diseases. Students will discuss the potential impact of current issues facing disease treatment and prevention. For pass standard, students will research infectious diseases caused by at least three of the five types of pathogen identified in the section B3 of the unit content. They will describe the mode of transmission of each pathogen, and the development and progression of the resultant infectious diseases. Students will describe methods to control the spread of, prevent, or treat the diseases. Students are expected to describe at least two current issues relating to the prevention and treatment of diseases. Students will be expected to use annotated diagrams to illustrate their descriptions. The diagrams will be detailed, clearly labelled and accurate."]}, {"aims": "C", "paras": ["For distinction standard, students will evaluate their practical methods and provide judgements on the accuracy of the procedures. They will be expected to consider factors such as: subjectivity (including standard protocols in the use of the haemocytometer), quantitative versus qualitative data gained, difficulty of skill and cost implications. Consideration will be given to modern clinical microbiology techniques. For example, why is the Gram stain commonly used in the first stage of the identification of microorganisms? Why might a microbiologist employ various methods of culturing bacteria and what are the purposes of selective and differential media in microorganism identification? Why would a microbiologist use streak plating to isolate individual colonies?", "For merit standard, students will be expected to culture microorganisms, but are not expected to use selective media. Students will carry out total and viable cell counts of cultures using serial dilutions, spread plating and haemocytometer. Students must compare the techniques used to cultivate microorganisms in terms of the quality of the results obtained. Comparisons will include the principles underlying the microbiological techniques used in terms of the staining procedures, colony characteristic identification methods, relevant aseptic technique and method of cultivation as well as the growth of the microorganisms in the different conditions. This should include an explanation of aseptic technique and a comparison of the methods of inoculation. Students are expected to explain the reasons for the health and safety procedures, aseptic technique and contamination issues, and to demonstrate skill and proficiency when carrying out these procedures. For pass standard, students will carry out morphological studies, microscopy and staining techniques to identify microorganisms. This should include the use of the Gram stain to identify Gram-negative and Gram-positive bacteria; colony characterisation from a mixed culture (possibly air-exposed Petri dishes or swabs from around the laboratory). This will also include correct use of aseptic technique to prepare growth medium and pour agar plates, which will be used to inoculate with microorganisms. Students will undertake a risk assessment before carrying out their studies. Students will develop skills in the following techniques: making a spread plate, making a smear slide, making a pour plate. They will then suitably and safely incubate these plates and make observations of the growth patterns."]}, {"aims": "D", "paras": ["For distinction standard, students will evaluate the provided protocol (methods, techniques and data) that they have used to test the susceptibility of microorganisms to antimicrobial agents. Students will use information from secondary sources in their evaluations. They will evaluate how effective their methods were in being able to analyse the effects and will suggest suitable alternatives or extensions to the methods or equipment that would enhance their results. Students will give a full account of the limitations of the procedures in terms of the health and safety procedures, aseptic technique and contamination opportunities, and will develop a rationale for improvement. They will also develop their evaluation to include the results of others, in order to provide a full and detailed report on the effect of antimicrobials on microbial growth. For merit standard, students will measure microbial growth with precision, leading to a coherent analysis of the results from which valid conclusions will be drawn. Students will use their results to analyse the effectiveness of the different agents inhibiting microbial growth. Their conclusions will lead to a consideration of the wider impact of their findings on prevention and treatment of infectious diseases.", "For pass standard, students will use given protocols to investigate the effects of antimicrobial agents on the growth of microorganisms. They will measure the effects of at least four antimicrobial agents on the microorganisms they have cultivated and will record their results, forming simple conclusions from their results comparing the effectiveness of these agents."]}]};
